import Fastify from 'fastify';

const app = Fastify({ logger: true }); // logs estruturados em JSON (pino)

app.get('/health', async () => ({ status: 'ok' })); // o objeto devolvido vira JSON

// Generics da rota tipam params, querystring, body e headers
app.get<{ Params: { id: string }; Querystring: { detalhes?: string } }>(
  '/users/:id',
  async (request, reply) => {
    const { id } = request.params;                      // id: string
    const detalhes = request.query.detalhes === 'true'; // query sempre chega como string
    if (id === '0') return reply.code(404).send({ erro: 'usuário não encontrado' });
    const user = { id, nome: 'Ana' };
    return detalhes ? { ...user, email: 'ana@ex.com' } : user;
  },
);

await app.listen({ port: 3000, host: '127.0.0.1' });
// curl localhost:3000/users/1?detalhes=true → {"id":"1","nome":"Ana","email":"ana@ex.com"}

import Fastify from 'fastify';
import { z } from 'zod';

const app = Fastify();

const CriarUserSchema = z.object({
  nome: z.string().min(2),
  email: z.email(),
  idade: z.number().int().min(18).optional(),
});
type CriarUser = z.infer<typeof CriarUserSchema>; // { nome: string; email: string; idade?: number }

app.post('/users', async (request, reply) => {
  // request.body chega como unknown: nunca confie no que veio da rede
  const parsed = CriarUserSchema.safeParse(request.body);
  if (!parsed.success) {
    return reply.code(400).send({ erro: 'dados inválidos', campos: z.flattenError(parsed.error).fieldErrors });
  }
  const user: CriarUser = parsed.data; // daqui em diante: validado E tipado
  return reply.code(201).send({ id: crypto.randomUUID(), ...user });
});

const ruim = await app.inject({ method: 'POST', url: '/users', payload: { nome: 'A', email: 'x' } });
console.log(ruim.statusCode, ruim.json());
// 400 { erro: 'dados inválidos', campos: { nome: [ 'Too small: ...' ], email: [ 'Invalid email address' ] } }

const bom = await app.inject({ method: 'POST', url: '/users', payload: { nome: 'Ana', email: 'ana@ex.com' } });
console.log(bom.statusCode); // 201

import Fastify, { type FastifyPluginAsync } from 'fastify';

// Declaration merging: avisa ao TS o que você pendurou na instância
declare module 'fastify' {
  interface FastifyInstance {
    config: { appName: string };
  }
}

// Um plugin agrupa rotas, hooks e dependências, com escopo próprio
const usersRoutes: FastifyPluginAsync = async (app) => {
  app.get('/', async () => [{ id: 1, nome: 'Ana' }]);
  app.get<{ Params: { id: string } }>('/:id', async (req) => ({ id: req.params.id }));
};

const app = Fastify();
app.decorate('config', { appName: 'tutor-api' });

// Hook: roda em toda requisição (log, autenticação, métricas)
app.addHook('onRequest', async (request) => {
  request.log.info({ url: request.url }, 'requisição recebida');
});

await app.register(usersRoutes, { prefix: '/users' }); // GET /users e GET /users/:id
app.get('/', async () => ({ app: app.config.appName })); // tipado graças ao declare module

console.log((await app.inject('/users/7')).json()); // { id: '7' }
console.log((await app.inject('/')).json());        // { app: 'tutor-api' }

import Fastify from 'fastify';

class HttpError extends Error {
  readonly statusCode: number;
  constructor(statusCode: number, message: string) {
    super(message);
    this.statusCode = statusCode;
  }
}

const app = Fastify();

app.get<{ Params: { id: string } }>('/pedidos/:id', async (req) => {
  if (req.params.id !== '1') throw new HttpError(404, 'pedido não encontrado'); // só lançar
  return { id: '1', total: 99.9 };
});

app.get('/bug', async () => {
  throw new Error('conexão com o banco recusada em 10.0.0.5:5432'); // detalhe interno
});

// Um lugar só decide o formato de TODAS as respostas de erro
app.setErrorHandler((error, request, reply) => {
  if (error instanceof HttpError) {
    return reply.code(error.statusCode).send({ erro: error.message });
  }
  request.log.error(error); // o detalhe vai para o log...
  return reply.code(500).send({ erro: 'erro interno' }); // ...e não vaza para o cliente
});

const r1 = await app.inject('/pedidos/2');
console.log(r1.statusCode, r1.json()); // 404 { erro: 'pedido não encontrado' }
const r2 = await app.inject('/bug');
console.log(r2.statusCode, r2.json()); // 500 { erro: 'erro interno' }

// ── app.ts ──
import Fastify from 'fastify';

// Fábrica: a mesma app serve para produção e para testes
export function buildApp() {
  const app = Fastify({ logger: process.env.NODE_ENV !== 'test' });
  app.get('/health', async () => ({ status: 'ok' }));
  return app;
}

// Só sobe o servidor quando este arquivo é executado direto
if (import.meta.main) {
  const app = buildApp();
  await app.listen({ port: Number(process.env.PORT ?? 3000), host: '0.0.0.0' });

  // Graceful shutdown: para de aceitar conexões e termina as que estão em andamento
  for (const sinal of ['SIGINT', 'SIGTERM'] as const) {
    process.once(sinal, async () => {
      await app.close();
      process.exit(0);
    });
  }
}

// ── app.test.ts ──
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { buildApp } from './app.ts';

// inject() simula a requisição sem abrir porta: rápido e isolado
test('GET /health responde ok', async () => {
  const app = buildApp();
  const res = await app.inject({ method: 'GET', url: '/health' });

  assert.equal(res.statusCode, 200);
  assert.deepEqual(res.json(), { status: 'ok' });
  await app.close();
});
